<?php
require_once 'functions.php';require_login();$s=$pdo->prepare('SELECT transaction_date,type,category,amount,description FROM transactions WHERE user_id=? ORDER BY transaction_date DESC,id DESC');$s->execute([uid()]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="expense-tracker-'.date('Y-m-d').'.csv"');$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['Date','Type','Category','Amount','Description']);while($r=$s->fetch())fputcsv($o,[$r['transaction_date'],$r['type'],$r['category'],$r['amount'],$r['description']]);fclose($o);exit;
